def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    # Fallback if no opponents
    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from immediate previous_trace
    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if isinstance(prev, dict) and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    max_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Pressure estimate: if someone paid very high yesterday, they likely secured water again or forced competition.
    high_pressure = max_prev_bid >= DAILY_SALARY * 0.85

    # Supply vs my need: when supply is tight relative to WATER_REQ, I should bid more to avoid missing.
    # Map supply to urgency (0..1)
    # ensure indices not needed; just compute scalars
    if MAX_SUPPLY <= MIN_SUPPLY:
        urgency = 0.5
    else:
        urgency = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
        if urgency < 0.0:
            urgency = 0.0
        if urgency > 1.0:
            urgency = 1.0

    # If supply is close to my requirement, missing water is costly.
    # Tightness: lower supply => higher tightness
    tightness = 1.0 - (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    if tightness < 0.0:
        tightness = 0.0
    if tightness > 1.0:
        tightness = 1.0

    # Base bid policy
    # - If high pressure yesterday, I bid enough to compete but not overextend.
    # - If my HP is low or I already had no_water_days, bid more.
    if my_hp <= 2.0 or my_no_water_days >= 2:
        base = DAILY_SALARY * (0.75 if not high_pressure else 0.95)
    elif my_hp <= 4.0:
        base = DAILY_SALARY * (0.6 if not high_pressure else 0.85)
    else:
        base = DAILY_SALARY * (0.5 if not high_pressure else 0.75)

    # Adjust by tightness: higher tightness -> higher bid
    base = base * (0.85 + 0.3 * tightness)

    # If high pressure, try to slightly beat the max_prev_bid but cap to budget.
    # Use a conservative step to avoid runaway bidding.
    if high_pressure and max_prev_bid > 0.0:
        target = max_prev_bid + 5.0
        bid = min(target, base)
    else:
        # Otherwise, anchor near base but ensure some competitiveness
        bid = base

    # Additional cap: never exceed budget
    bid = min(bid, my_budget)
    if bid < 0.0:
        bid = 0.0

    # If budget is extremely low, bid minimally to conserve.
    if my_budget <= DAILY_SALARY * 0.15:
        bid = min(my_budget, DAILY_SALARY * 0.25)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return float(min(budget, 20.0))

    winners_est = max(1, int(supply // WATER_REQ))
    opp_count = len(alive)

    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in alive:
        if opp.get('budget', 0) >= DAILY_SALARY * 2:
            rich_opp += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    my_urgent = hp <= 3 or no_water >= 1
    severe_urgent = hp <= 2 or no_water >= 2
    scarce = winners_est <= 1
    contested = opp_count >= winners_est + 1

    if severe_urgent:
        bid = max(0.92 * DAILY_SALARY, highest_prev + 3.0)
    elif scarce:
        if contested:
            bid = max(0.82 * DAILY_SALARY, min(0.98 * DAILY_SALARY, highest_prev + 2.0))
        else:
            bid = 0.72 * DAILY_SALARY
    else:
        if my_urgent:
            bid = max(0.68 * DAILY_SALARY, avg_prev * 0.72)
        else:
            bid = 0.34 * DAILY_SALARY
            if highest_prev > 180:
                bid = 0.22 * DAILY_SALARY
            elif highest_prev > 120:
                bid = 0.28 * DAILY_SALARY
            elif highest_prev > 70:
                bid = 0.36 * DAILY_SALARY

    if urgent_opp >= 2 and scarce:
        bid = max(bid, highest_prev + 1.5)
    elif urgent_opp == 0 and winners_est >= 2:
        bid = min(bid, 0.30 * DAILY_SALARY)

    if rich_opp >= 2 and scarce:
        bid = max(bid, 0.88 * DAILY_SALARY)

    if budget < DAILY_SALARY:
        bid = min(bid, max(0.0, budget * 0.78))
    else:
        bid = min(bid, budget)

    min_guard = 6.0 if not my_urgent else 18.0
    bid = max(min_guard if budget >= min_guard else 0.0, bid)
    bid = min(bid, budget)

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    current_day = day_context['day']
    current_supply = day_context['supply']
    my_hp = my_status['hp']
    my_budget = my_status['budget']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    bid_amount = DAILY_SALARY * 0.55

    # Survival Mode: If HP is critically low, bid very aggressively
    if my_hp <= WATER_REQ:
        bid_amount = DAILY_SALARY * 0.95
    elif my_hp <= WATER_REQ * 1.5:
        bid_amount = DAILY_SALARY * 0.8
    elif my_hp >= EPISODE_DAYS * WATER_REQ:
        bid_amount = DAILY_SALARY * 0.3

    # End Game Pressure: Increase bid towards the end of the episode
    remaining_days = EPISODE_DAYS - current_day
    if remaining_days <= 2:
        if my_hp <= WATER_REQ * 2:
            bid_amount = max(bid_amount, DAILY_SALARY * 0.9)
        else:
            bid_amount = max(bid_amount, DAILY_SALARY * 0.7)
    elif remaining_days <= 4:
        if my_hp <= WATER_REQ * 1.5:
            bid_amount = max(bid_amount, DAILY_SALARY * 0.75)

    # React to Opponents' Yesterday's Bids
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        average_prev_bid = sum(yesterday_bids) / len(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.7:
            bid_amount = max(bid_amount, highest_prev_bid * 1.05)
        elif highest_prev_bid >= DAILY_SALARY * 0.4:
            bid_amount = max(bid_amount, average_prev_bid * 1.1)
        else:
            bid_amount = max(bid_amount, highest_prev_bid + 5)

    # Adjust based on Supply vs. Demand
    estimated_total_water_needed = sum([o['water_requirement'] for o in alive_opponents]) + WATER_REQ

    if current_supply < estimated_total_water_needed * 0.8:
        bid_amount *= 1.25
    elif current_supply < estimated_total_water_needed * 1.2:
        bid_amount *= 1.1
    elif current_supply > estimated_total_water_needed * 2:
        bid_amount *= 0.8
    elif current_supply > estimated_total_water_needed * 1.5:
        bid_amount *= 0.9

    min_effective_bid = DAILY_SALARY * 0.2
    if num_alive_opponents > 0 and current_supply < estimated_total_water_needed:
        min_effective_bid = DAILY_SALARY * 0.4
    bid_amount = max(bid_amount, min_effective_bid)

    final_bid = min(my_budget, bid_amount)
    final_bid = max(0.0, final_bid)

    return final_bid

